#!/usr/bin/env python
"""Validate CDLoot/Data/Dungeons.lua (generated by gen_cdloot_dungeons.py).

1. Compiles + executes the file in a real Lua 5.1 (lupa.lua51) with `...` = ("CDLoot", ns).
2. Checks the shape: dungeon/boss fields and types, unique boss keys per dungeon, integer IDs, no duplicate IDs
   within a list, no Badge of Justice, no gems in heroic lists.
3. Re-derives every boss list INDEPENDENTLY from the raw text of AtlasLoot's data-tbc.lua (line-based scan, not the
   generator's tokenizer) with the documented skip rules, and compares with the loaded tables (exact order).
4. Prints a side-by-side spot-check (ID, AtlasLoot comment, Questie name) for selected bosses.
5. Overlap with the raid DB (CDLoot/Data/Items.lua, loaded read-only in Lua) and items shared across dungeon bosses.

Usage (from SCRATCH):  luaenv\\Scripts\\python.exe validate_dungeons.py [path\\to\\Dungeons.lua]
"""
import os
import re
import sys
from collections import defaultdict

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, "tools"))
sys.path.insert(0, HERE)
import luabc  # noqa: E402,F401  (puts lupa on sys.path)
from lupa import lua51  # noqa: E402
import gen_cdloot_dungeons as GD  # noqa: E402

ADDONS = GD.ADDONS
DUNGEONS_LUA = sys.argv[1] if len(sys.argv) > 1 else GD.OUT_LUA_DEFAULT
ITEMS_LUA = GD.P_RAID_ITEMS
ATLAS = GD.G.P_ATLAS_RAIDS
SPOT = [("HellfireRamparts", "Gargolmar"), ("ShatteredHalls", "Kargath"), ("ShadowLabyrinth", "Murmur"),
        ("BlackMorass", "Aeonus"), ("Mechanar", "CacheOfTheLegion"), ("MagistersTerrace", "Kaelthas"),
        ("SethekkHalls", "Ikiss")]

errors = []


def err(msg):
    errors.append(msg)
    print("ERROR", msg)


def load_ns(lua, path):
    src = open(path, encoding="utf-8").read()
    r = lua.eval("function(s, n) local f, e = loadstring(s, n); return {f = f, e = e} end")(src, "@" + os.path.basename(path))
    f, e = r.f, r.e
    if f is None:
        raise SystemExit(f"Lua 5.1 compile error in {path}: {e}")
    ns = lua.table()
    f("CDLoot", ns)
    return ns


def lua_list(t):
    if t is None:
        return None
    n = len(t)
    return [t[i] for i in range(1, n + 1)]


def main():
    lua = lua51.LuaRuntime(unpack_returned_tuples=True)
    print("Lua runtime:", lua.eval("_VERSION"))
    ns = load_ns(lua, DUNGEONS_LUA)
    print(f"compiled + executed OK: {DUNGEONS_LUA}")
    D = ns.Data.Dungeons
    assert D is not None, "ns.Data.Dungeons missing"
    questie = GD.load_questie_items_full()

    # ---------------------------------------------------------------- shape
    dungeons = []
    for di in range(1, len(D) + 1):
        d = D[di]
        for f, typ in (("key", str), ("name", str), ("phase", int), ("instanceID", int)):
            v = d[f]
            if not isinstance(v, typ):
                err(f"dungeon #{di} field {f} = {v!r}")
        bosses = []
        keys = set()
        for bi in range(1, len(d.bosses) + 1):
            b = d.bosses[bi]
            if b.key in keys:
                err(f"{d.key}: duplicate boss key {b.key}")
            keys.add(b.key)
            if not isinstance(b.name, str):
                err(f"{d.key}/{b.key}: name")
            npcs = lua_list(b.npcIDs)
            if npcs is None or not all(isinstance(x, int) and x > 0 for x in npcs):
                err(f"{d.key}/{b.key}: npcIDs {npcs}")
            objs = lua_list(b.objectIDs) if b.objectIDs is not None else []
            if not all(isinstance(x, int) and x > 0 for x in objs):
                err(f"{d.key}/{b.key}: objectIDs {objs}")
            if not npcs and not objs and not b.isTrash:
                err(f"{d.key}/{b.key}: neither npcIDs nor objectIDs")
            for flag in ("isTrash", "isChest"):
                if b[flag] not in (None, True):
                    err(f"{d.key}/{b.key}: {flag} = {b[flag]!r}")
            if b.encounterID is not None and not isinstance(b.encounterID, int):
                err(f"{d.key}/{b.key}: encounterID")
            lists = {}
            for fld in ("items", "heroicItems"):
                lst = lua_list(b[fld])
                if lst is None:
                    err(f"{d.key}/{b.key}: {fld} missing")
                    lst = []
                if not all(isinstance(x, int) and x > 0 for x in lst):
                    err(f"{d.key}/{b.key}: {fld} non-integer")
                if len(set(lst)) != len(lst):
                    err(f"{d.key}/{b.key}: {fld} has duplicates")
                if 29434 in lst:
                    err(f"{d.key}/{b.key}: Badge of Justice in {fld}")
                if fld == "heroicItems":
                    gems = [x for x in lst if (questie.get(x) or {}).get("cls") == GD.QUESTIE_CLASS_GEM]
                    if gems:
                        err(f"{d.key}/{b.key}: gems in heroicItems {gems}")
                lists[fld] = lst
            if not lists["items"] and not lists["heroicItems"]:
                err(f"{d.key}/{b.key}: both lists empty")
            bosses.append({"key": b.key, "name": b.name, "npcIDs": npcs, "objectIDs": objs, **lists})
        dungeons.append({"key": d.key, "name": d.name, "phase": d.phase, "instanceID": d.instanceID, "bosses": bosses})
    nb = sum(len(d["bosses"]) for d in dungeons)
    print(f"shape OK: {len(dungeons)} dungeons, {nb} bosses, boss keys unique per dungeon: "
          f"{all(len({b['key'] for b in d['bosses']}) == len(d['bosses']) for d in dungeons)}")

    # ---------------------------------------------------------------- independent re-derivation from raw AtlasLoot text
    lines = open(ATLAS, encoding="utf-8-sig").read().splitlines()
    raw = {}          # alKey -> list of bosses {name, npc, obj, vendor, wrath, N:[(id,cmt)], H:[...]}
    cur_d = cur_b = cur_diff = None
    depth_skip = None
    for ln in lines:
        m = re.match(r'^data\["([^"]+)"\]\s*=\s*\{', ln)
        if m:
            cur_d = m.group(1)
            raw[cur_d] = []
            cur_b = cur_diff = None
            continue
        if cur_d is None:
            continue
        if "GameVersion_GE(AtlasLoot.WRATH_VERSION_NUM" in ln:
            depth_skip = True
            cur_b = {"name": None, "wrath": True, "N": [], "H": [], "vendor": False}
            raw[cur_d].append(cur_b)
            continue
        m = re.match(r'^\s*name\s*=\s*AL\["(.*)"\],', ln)
        if m:
            if cur_b is not None and cur_b.get("wrath") and cur_b["name"] is None:
                cur_b["name"] = m.group(1)
                continue
            cur_b = {"name": m.group(1), "wrath": False, "N": [], "H": [], "vendor": False}
            raw[cur_d].append(cur_b)
            cur_diff = None
            continue
        if cur_b is None:
            continue
        if 'specialType = "vendor"' in ln:
            cur_b["vendor"] = True
        m = re.match(r"^\s*\[(NORMAL|HEROIC)_DIFF\]\s*=\s*\{", ln)
        if m:
            cur_diff = "N" if m.group(1) == "NORMAL" else "H"
            continue
        m = re.match(r"^\s*\{\s*\d+\s*,\s*(\d+)\s*[,}].*?(?:--\s*(.*))?$", ln)
        if m and cur_diff:
            cur_b[cur_diff].append((int(m.group(1)), (m.group(2) or "").strip()))
    # apply rules
    derived = {}
    for al_key, (ck, _, _) in GD.DUNGEONS.items():
        out_b = []
        for b in raw.get(al_key, []):
            if b["wrath"] or b["vendor"]:
                continue
            res = {}
            for tag, fld in (("N", "items"), ("H", "heroicItems")):
                seen, lst = set(), []
                for iid, _c in b[tag]:
                    if iid == 29434 or iid in seen:
                        continue
                    if tag == "H" and (questie.get(iid) or {}).get("cls") == GD.QUESTIE_CLASS_GEM:
                        continue
                    seen.add(iid)
                    lst.append(iid)
                res[fld] = lst
            out_b.append((b["name"], res, b))
        derived[ck] = out_b
    mism = 0
    compared = 0
    for d in dungeons:
        db = derived.get(d["key"], [])
        if len(db) != len(d["bosses"]):
            err(f"{d['key']}: boss count {len(d['bosses'])} vs raw re-derivation {len(db)} ({[x[0] for x in db]})")
            continue
        for b, (rname, res, _) in zip(d["bosses"], db):
            for fld in ("items", "heroicItems"):
                compared += 1
                if b[fld] != res[fld]:
                    mism += 1
                    err(f"{d['key']}/{b['key']} ({rname}) {fld}: generated {b[fld]} != raw {res[fld]}")
    print(f"independent re-derivation from raw data-tbc.lua: {compared} lists compared, {mism} mismatches")

    # ---------------------------------------------------------------- spot checks
    by = {(d["key"], b["key"]): (b, d) for d in dungeons for b in d["bosses"]}
    rawmap = {}
    for dk, lst in derived.items():
        dd = next(x for x in dungeons if x["key"] == dk)
        for b, (rname, res, rb) in zip(dd["bosses"], lst):
            rawmap[(dk, b["key"])] = rb
    for dk, bk in SPOT:
        b, d = by[(dk, bk)]
        rb = rawmap[(dk, bk)]
        print(f"\n--- spot-check {d['name']} / {b['name']}  npcIDs={b['npcIDs']} objectIDs={b['objectIDs']}")
        for tag, fld in (("N", "items"), ("H", "heroicItems")):
            src_rows = rb[tag]
            gen = b[fld]
            print(f"  [{fld}] AtlasLoot rows={len(src_rows)} generated={len(gen)}")
            gi = 0
            for iid, cmt in src_rows:
                qn = (questie.get(iid) or {}).get("name")
                if gi < len(gen) and gen[gi] == iid:
                    mark = "ok  "
                    gi += 1
                else:
                    mark = "SKIP"
                print(f"    {mark} {iid:6d}  AtlasLoot: {cmt:40s} Questie: {qn}")
            if gi != len(gen):
                err(f"spot-check {dk}/{bk} {fld}: generated list not a prefix-aligned subsequence of AtlasLoot rows")

    # ---------------------------------------------------------------- overlaps
    rns = load_ns(lua, ITEMS_LUA)
    raid_ids = defaultdict(list)
    R = rns.Data.Raids
    for ri in range(1, len(R) + 1):
        r = R[ri]
        for bi in range(1, len(r.bosses) + 1):
            b = r.bosses[bi]
            for x in lua_list(b["items"]):
                raid_ids[x].append(f"{r.key}/{b.key}")
    dsrc = defaultdict(list)
    for d in dungeons:
        for b in d["bosses"]:
            for fld, tag in (("items", "N"), ("heroicItems", "H")):
                for x in b[fld]:
                    dsrc[x].append(f"{d['key']}/{b['key']}({tag})")
    ov = sorted(set(raid_ids) & set(dsrc))
    print(f"\nraid Items.lua: {len(raid_ids)} item IDs; dungeon DB: {len(dsrc)} item IDs; overlap: {len(ov)}")
    for x in ov:
        print(f"  overlap {x} {(questie.get(x) or {}).get('name')}: raid {raid_ids[x]} / dungeon {dsrc[x]}")
    shared = {x: v for x, v in dsrc.items() if len({s.rsplit('(', 1)[0] for s in v}) > 1}
    print(f"items shared across dungeon bosses: {len(shared)}")
    for x, v in sorted(shared.items()):
        print(f"  {x} {(questie.get(x) or {}).get('name')}: {v}")
    both = sum(1 for x, v in dsrc.items() if any(s.endswith("(N)") for s in v) and any(s.endswith("(H)") for s in v))
    print(f"items in both a normal and a heroic list: {both}; heroic-only: {sum(1 for v in dsrc.values() if all(s.endswith('(H)') for s in v))}; normal-only: {sum(1 for v in dsrc.values() if all(s.endswith('(N)') for s in v))}")

    print(f"\n{'FAILED' if errors else 'ALL CHECKS PASSED'} ({len(errors)} errors)")
    sys.exit(1 if errors else 0)


if __name__ == "__main__":
    main()
